def w3(n):
    p = []
    if n // 100:
        p.append('yüz' if n // 100 == 1 else ONES[n // 100] + ' yüz')
    if (n % 100) // 10:
        p.append(TENS[(n % 100) // 10])
    if n % 10:
        p.append(ONES[n % 10])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    p = []
    for v, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q = n // v
        if q:
            p.append('bin' if (v == 1000 and q == 1) else w3(q) + ' ' + nm)
            n = n % v
    if n:
        p.append(w3(n))
    return ' '.join(p)
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def amt(x, c):
    k = int(round(abs(num(x)) * 100))
