def cop(t):
    v = [ch for ch in t if ch in 'aeıioöuü']
    lv = v[-1] if v else 'a'
    h = 'ı' if lv in 'aı' else ('i' if lv in 'ei' else ('u' if lv in 'ou' else 'ü'))
    return t + ('t' if t[-1] in 'çfhkpsşt' else 'd') + h + 'r'
def digits(s):
    return ' '.join(['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz'][int(ch)] for ch in str(s) if ch.isdigit())
